import os
FONTS='<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,800&family=Hanken+Grotesk:wght@400;500;700&display=swap" rel="stylesheet">'
def nav(cur):
    def a(h,t): return f'<a href="{h}"'+(' aria-current="page"' if cur==h else '')+f'>{t}</a>'
    links = a("/ai","AI") + a("/books","Books") + a("/felasweekly","Fela's Weekly") + a("/about","About")
    return '<nav><div class="wrap"><a href="/" style="margin:0;color:#fff;display:flex;align-items:center;gap:10px"><img src="/assets/logo.png" alt="" width="36" height="36"><b>Fela Adejumo</b></a><div class="links">' + links + '<a class="cta" href="/about#talk" style="color:#fff">Let\'s talk</a></div></div></nav>'
FOOT='<footer><div class="wrap"><b>Fela Adejumo</b><p>Writer. Creator. Builder.</p><div class="l"><a href="/ai">AI</a><a href="/books">Books</a><a href="/felasweekly">Fela\'s Weekly</a><a href="/about">About</a></div><div class="l"><a href="https://felasbbq.com">Fela\'s BBQ</a><a href="https://untamablecollective.com">Untamable Collective</a></div><div class="l"><a href="https://instagram.com/felaadejumo" rel="noopener">Instagram</a><a href="https://x.com/felaadejumo" rel="noopener">X</a><a href="https://linkedin.com/in/richardadejumo" rel="noopener">LinkedIn</a><a href="mailto:hi@felaadejumo.com">hi@felaadejumo.com</a></div><p style="margin-top:20px">© <span id="yr">2026</span> Fela Adejumo</p></div></footer><script>document.getElementById("yr").textContent=new Date().getFullYear()</script>'
def page(path,cur,title,desc,body):
    h=f'<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{title}</title><meta name="description" content="{desc}"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:type" content="website">{FONTS}<link rel="icon" href="/assets/favicon.png"><link rel="stylesheet" href="/assets/site.css"></head><body>{nav(cur)}{body}{FOOT}</body></html>'
    os.makedirs(os.path.dirname(path) or '.',exist_ok=True); open(path,'w').write(h)
BOOKS=[
("Aníkúlápò's Afrobeat","anikulapos-afrobeat","How Fela Anikulapo-Kuti's Afrobeat was born, what it meant, and how it differs from today's Afrobeats.","This book delves into the rich history and cultural significance of the genre-defining music of the legendary Fela Anikulapo-Kuti. It charts the origin, evolution and impact of Afrobeat on Nigerian culture and society, and its role in shaping the political and social landscape of Nigeria and Africa in the 1970s.\nIt also examines the power of Fela's live performances, how Afrobeat became the soundtrack of the struggle, and the lasting impact of the genre on contemporary music. The final chapter draws a clear distinction between “Afrobeat” and the modern “Afrobeats.”\nA must-read for music enthusiasts, cultural historians and anyone seeking to understand the legacy of Afrobeat and its political and cultural significance.","https://www.amazon.com/dp/B0BW23RTCP"),
("The Top Secrets of the Music Business","top-secrets-music-business","The parts of the music industry rarely talked about: myths, truths and new developments for creatives.","A detailed and informative look at the secret parts of the music industry that are rarely acknowledged in public: the myths, the truths, and the new developments in the music business that are crucial for creatives and industry professionals to know.\nSubtitle: An insider's guide for independent and upcoming creatives.","https://www.amazon.com/dp/B0BT4ZFTXP"),
("Productivity Hacks for the Virtual Worker","productivity-hacks","The guide to time management for remote workers.","The guide to time management for remote workers.","https://www.amazon.com/dp/B0BVD2M5XX"),
("Threads of Time","threads-of-time","From the first skins used for warmth to the silks of royalty: the history of fashion.","Fashion has been a part of humanity for centuries, but do you ever stop to wonder where it all began? This book takes you on a journey through the history of fashion, from the first skins used for warmth to the silks of royalty and the innovative designs of today.\nIt explores the evolution of clothing and style through the ages.","https://www.amazon.com/dp/B0C2RH7JQJ")]
def books(big=False,n=4):
    out=[]
    for t,f,sh,lg,u in BOOKS[:n]:
        body=''.join(f'<p>{x}</p>' for x in lg.split('\n')) if big else f'<p>{sh}</p>'
        link=f'<a class="btn" href="{u}" target="_blank" rel="noopener">Get it on Amazon ↗</a>' if big else f'<a href="{u}" target="_blank" rel="noopener" style="font-weight:700;font-size:.9rem">Amazon ↗</a>'
        out.append(f'<div class="book"><img src="/assets/books/{f}.png" alt="{t} book mockup" loading="lazy"><h3>{t}</h3>{body}{link}</div>')
    return '<div class="books'+(' big' if big else '')+'">'+''.join(out)+'</div>'
